"""Start and stop a world's server (/api, /mcp and the built UI) as a subprocess."""

import asyncio
import contextlib
import os
import socket
import time
from pathlib import Path

import httpx


def free_port() -> int:
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0))
        return sock.getsockname()[1]


def resolve_world_python(template_dir: Path, configured: Path | None) -> Path:
    """The shared interpreter that runs every world (its dependencies are [base])."""
    python = (
        configured or template_dir / ".pixi" / "envs" / "default" / "bin" / "python"
    )
    if not python.exists():
        raise RuntimeError(
            f"world interpreter not found at {python}; run "
            "`pixi install --manifest-path src/worlds-template/pixi.toml`"
        )
    return python.absolute()


async def start_world(
    world_dir: Path, python: Path, port: int
) -> asyncio.subprocess.Process:
    world_dir = world_dir.resolve()  # the server runs with this as its cwd
    env = {**os.environ, "PYTHONPATH": str(world_dir), "PORT": str(port)}
    return await asyncio.create_subprocess_exec(
        str(python),
        "-m",
        "uvicorn",
        "server.api:app",
        "--host",
        "127.0.0.1",
        "--port",
        str(port),
        "--log-level",
        "warning",
        cwd=world_dir,
        env=env,
        stdin=asyncio.subprocess.DEVNULL,
        stdout=asyncio.subprocess.DEVNULL,
        stderr=asyncio.subprocess.PIPE,
    )


async def wait_healthy(
    port: int, process: asyncio.subprocess.Process, timeout: float
) -> None:
    """Return when /healthz answers; raise if the process dies or the timeout passes."""
    deadline = time.monotonic() + timeout
    async with httpx.AsyncClient(timeout=2) as http:
        while time.monotonic() < deadline:
            if process.returncode is not None:
                error = b""
                if process.stderr is not None:
                    error = await process.stderr.read()
                raise RuntimeError(
                    f"world server exited with {process.returncode}: "
                    f"{error.decode(errors='replace')[-600:]}"
                )
            try:
                if (
                    await http.get(f"http://127.0.0.1:{port}/healthz")
                ).status_code == 200:
                    return
            except httpx.HTTPError:
                pass
            await asyncio.sleep(0.15)
    raise RuntimeError(
        f"world server did not answer on port {port} within {timeout:.0f}s"
    )


async def stop_world(process: asyncio.subprocess.Process) -> None:
    if process.returncode is None:
        process.terminate()
        try:
            await asyncio.wait_for(process.wait(), 5)
        except TimeoutError:
            process.kill()
            with contextlib.suppress(Exception):
                await process.wait()
// Connection to the world server (server/api.py, proxied under /api by Vite).
// URLs are relative so the UI also works behind a path prefix (/api/play/<id>/).
import { useCallback, useEffect, useRef, useState } from "react";

const POLL_MS = 1000;
const OFFLINE_POLL_MS = 5000;

/**
 * Current world state and a `refresh()` to fetch it right away (e.g. after an
 * action). Polls `GET /api/state` every second; until the server answers (or
 * while it is down) the last known state, initially `mock`, is kept, so the UI
 * also works without a server. Unchanged responses keep the same object, so
 * nothing re-renders.
 */
export function useWorldState<T>(mock: T): [T, () => Promise<void>] {
  const [state, setState] = useState<T>(mock);
  const last = useRef("");
  const fetchState = useCallback(async (): Promise<boolean> => {
    try {
      const res = await fetch("api/state");
      if (!res.ok) return false;
      const text = await res.text();
      if (text !== last.current) {
        last.current = text;
        setState(JSON.parse(text) as T);
      }
      return true;
    } catch {
      return false; // No server: keep the current (mock) state.
    }
  }, []);

  useEffect(() => {
    let alive = true;
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      const ok = await fetchState();
      // Back off while the server is unreachable to keep the console quiet.
      if (alive) timer = setTimeout(poll, ok ? POLL_MS : OFFLINE_POLL_MS);
    };
    void poll();
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [fetchState]);

  const refresh = useCallback(async () => {
    await fetchState();
  }, [fetchState]);
  return [state, refresh];
}

/** Outcome of a request: `error` is the server's reason when it was rejected. */
export interface Sent { ok: boolean; error?: string }

async function post(path: string, body: unknown): Promise<Sent> {
  try {
    const res = await fetch(path, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (res.ok) return { ok: true };
    const detail = await res.json().then((d: { detail?: unknown }) => d.detail).catch(() => null);
    return { ok: false, error: typeof detail === "string" ? detail : `HTTP ${res.status}` };
  } catch {
    return { ok: false, error: "No connection to the world server" };
  }
}

/** Send a player action (queued until the next advance) or a UI control. */
export function sendAction(id: string, args: Record<string, unknown> = {}): Promise<Sent> {
  return post("api/action", { id, args });
}

/** Remove queued action `index` of this step. */
export function unqueue(index: number): Promise<Sent> {
  return post("api/unqueue", { index });
}

/** Start a new episode at difficulty level 1-3 (the website opens worlds as `?level=N`). */
export function resetToLevel(level: number): Promise<Sent> {
  return post("api/reset", { level });
}
// [base] The server's state (dumped by tests/backend/test_contract.py) matches `mockState`
// and the world view and controls render it at every level.
import { render } from "@testing-library/react";
import { expect, test } from "vitest";
import { mockState, toControls, WorldView } from "./World";

const samples = import.meta.glob<{ default: Record<string, unknown> }>("./__samples__/*.json", { eager: true });
const files = Object.keys(samples).sort();
const load = (file: string) => samples[file].default as unknown as typeof mockState;

type Json = unknown;

/** Every key of `mock` must exist in `real` with the same primitive type (recursively). */
function missing(mock: Json, real: Json, path = "state"): string[] {
  if (mock === null || mock === undefined || real === null) return []; // optional or nullable in the state
  if (Array.isArray(mock)) {
    if (!Array.isArray(real)) return [`${path}: expected an array`];
    return mock.length && real.length ? missing(mock[0], real[0], `${path}[0]`) : [];
  }
  if (typeof mock === "object") {
    if (typeof real !== "object" || real === null) return [`${path}: expected an object`];
    return Object.entries(mock as Record<string, Json>).flatMap(([k, v]) =>
      k in (real as object) ? missing(v, (real as Record<string, Json>)[k], `${path}.${k}`) : [`${path}.${k}: missing`],
    );
  }
  return typeof mock === typeof real ? [] : [`${path}: expected ${typeof mock}, got ${typeof real}`];
}

